-- Update the first-visit copy without resetting introduction views.
update arsenich_destination_intro
   set windows = jsonb_set(windows, '{0,body}', '"Бонусные игры прокачивают отдельные способности игрока и проходят по своим правилам. Перед стартом открой карточку и прочитай условие.\n\n- Сверху можно переключаться между видами бонусных игр.\n- На карточке указаны цель игры и доступные попытки.\n- Улучшай личный рекорд или побей общий рекорд локации, чтобы получить дополнительные звёзды и опыт."'::jsonb),
       revision = revision + 1,
       updated_at = now()
 where destination_key = 'bonus-games'
   and windows #> '{0,body}' is distinct from '"Бонусные игры прокачивают отдельные способности игрока и проходят по своим правилам. Перед стартом открой карточку и прочитай условие.\n\n- Сверху можно переключаться между видами бонусных игр.\n- На карточке указаны цель игры и доступные попытки.\n- Улучшай личный рекорд или побей общий рекорд локации, чтобы получить дополнительные звёзды и опыт."'::jsonb;
